import csv

with open('/app/dataset/hospital_compensation_registry.csv') as f:
    reader = csv.DictReader(f)
    rows = list(reader)

# Look at who lists these high-EC no-claim patients - maybe there's a bereavement or family support claim from someone connected?
for target in ['PAT_065', 'PAT_084', 'PAT_203', 'PAT_267', 'PAT_273']:
    print(f'=== {target} ===')
    listers = []
    for r in rows:
        if r['emergency_contact_patient_id'] == target:
            listers.append(r['patient_id'])
    print('listed by:', listers)
    # check if any lister has bereavement/family support
    for r in rows:
        if r['patient_id'] in listers:
            if any(k in (r['compensation_reason'] or '').lower() for k in ['bereave', 'family', 'death']):
                print('  *', r['patient_id'], r['compensation_reason'], r['direct_payment_usd'])
    print()
